{"content": "#!/usr/bin/env python3
"""
Fix Tomorrow Remembered review PDF:
1. Replace base64 images with file:// paths (WeasyPrint renders these)
2. Add target-counter page numbers to TOC
3. Regenerate PDF
"""

import re
import os
import subprocess

BASE = '/home/bob/books/The_Unwritten_Future/output'
HTML_PATH = f'{BASE}/Tomorrow_Remembered.html'
PDF_PATH = f'{BASE}/Tomorrow_Remembered_Review.pdf'
IMG_DIR = f'{BASE}/part_images'

with open(HTML_PATH) as f:
    html = f.read()

print(f"HTML size: {len(html):,} chars")

# Step 1: Replace base64 image src with file:// paths
img_files = {
    'Part One: The Ignition': 'part1_ignition.png',
    'Part Two: The Building': 'part2_building.png',
    'Part Three: The Particle and The Person': 'part3_particle.png',
    'Part Four: Building Forward': 'part4_forward.png',
    'Part Five: The Futures Beyond': 'part5_future.png',
}

for alt_text, filename in img_files.items():
    file_url = f'file://{IMG_DIR}/{filename}'
    # Find the img tag for this alt text and replace its src
    # Pattern: <img src="data:image/png;base64,..." alt="Illustration for Part ...">
    pattern = rf'(<img\s+src=")data:image/png;base64,[^"]+(" alt="Illustration for {re.escape(alt_text)}")'
    replacement = rf'\1{file_url}\2'
    html = re.sub(pattern, replacement, html)
    print(f"  Replaced image: {alt_text} -> {file_url}")

# Step 2: Add id attributes to chapter headings and convert TOC to use links
# First, add IDs to chapter h2 tags
chapter_ids = {}
for m in re.finditer(r'<h2 class="chapter-title">(Chapter \w+: .*?)</h2>', html):
    ch_text = m.group(1)
    ch_id = ch_text.lower().replace(' ', '-').replace(':', '')[:30]
    ch_id = re.sub(r'[^a-z0-9-]', '', ch_id)
    chapter_ids[ch_text] = ch_id
    html = html.replace(
        f'<h2 class="chapter-title">{ch_text}</h2>',
        f'<h2 class="chapter-title" id="{ch_id}">{ch_text}</h2>'
    )
print(f"  Added IDs to {len(chapter_ids)} chapters")

# Also add IDs to part title h1
part_ids = {}
for m in re.finditer(r'<h1 class="part-title">(Part \w+: .*?)</h1>', html):
    pt_text = m.group(1)
    pt_id = pt_text.lower().replace(' ', '-').replace(':', '')
    pt_id = re.sub(r'[^a-z0-9-]', '', pt_id)
    part_ids[pt_text] = pt_id
    html = html.replace(
        f'<h1 class="part-title">{pt_text}</h1>',
        f'<h1 class="part-title" id="{pt_id}">{pt_text}</h1>'
    )
print(f"  Added IDs to {len(part_ids)} parts")

# Step 3: Convert TOC entries to links with target-counter
# Current TOC pattern: <p class="part">Part One: The Ignition</p>
#                 or:  <p class="chapter">Chapter One: The Shock</p>

# Parts
for pt_text, pt_id in part_ids.items():
    old_toc = f'<p class="part">{pt_text}</p>'
    new_toc = f'<p class="part"><a href="#{pt_id}">{pt_text}</a></p>'
    html = html.replace(old_toc, new_toc)

# Chapters
for ch_text, ch_id in chapter_ids.items():
    old_toc = f'<p class="chapter">{ch_text}</p>'
    new_toc = f'<p class="chapter"><a href="#{ch_id}">{ch_text}</a></p>'
    html = html.replace(old_toc, new_toc)

print("  Converted TOC to clickable links")

# Step 4: Add CSS for TOC page numbers using target-counter
toc_counter_css = '''
/* TOC page numbers */
.toc a {
    text-decoration: none;
    color: inherit;
}
.toc a::after {
    content: "  " target-counter(attr(href url), page);
    float: right;
    color: #555;
    font-size: 10pt;
}
.toc .part a::after {
    font-weight: bold;
}
.toc .chapter a::after {
    font-weight: normal;
}
'''

# Insert the CSS before the closing </style>
html = html.replace('</style>', toc_counter_css + '\n</style>')

print("  Added TOC page number CSS")

# Step 5: Fix the img CSS to ensure WeasyPrint respects them
# Add print-specific image handling
img_fix_css = '''
/* Force images to render */
.part-image {
    max-width: 3.5in;
    max-height: 4in;
    display: block;
    margin: 0 auto;
    page-break-inside: avoid;
}
'''

if '/* Force images to render */' not in html:
    html = html.replace(
        '.part-image {\n    max-width: 3.5in;\n    max-height: 4in;\n    display: block;\n    margin: 0 auto;\n}',
        img_fix_css
    )

print("  Fixed image CSS")

# Write modified HTML
with open(HTML_PATH, 'w') as f:
    f.write(html)

print(f"\nWritten modified HTML: {len(html):,} chars")

# Step 6: Generate PDF
print("\nGenerating PDF...")
result = subprocess.run(
    ['weasyprint', HTML_PATH, PDF_PATH],
    capture_output=True, text=True, timeout=120
)

if result.returncode == 0:
    pdf_size = os.path.getsize(PDF_PATH)
    print(f"✓ PDF generated: {pdf_size:,} bytes")
else:
    print(f"✗ Error: {result.stderr}")

# Verify
print("\nVerification:")
# Check images in the modified HTML
img_srcs = re.findall(r'<img\s+src="([^"]+)"', html)
for src in img_srcs:
    if 'base64' in src:
        print(f"  ⚠ Still has base64 image: {src[:50]}...")
    elif src.startswith('file://'):
        exists = os.path.exists(src[7:])
        print(f"  {'✓' if exists else '✗'} File image: {src} {'(MISSING!)' if not exists else ''}")

# Count TOC links
toc_links = html.count('<a href="#')
print(f"  TOC links: {toc_links}")

# Count target-counter CSS usage
tcc = html.count('target-counter')
print(f"  target-counter rules: {tcc}")

print("\nDone!")
