"""Regenerate 5 part divider images at 2048x2048 for crisp print quality."""
import os, base64, time, json, requests
from pathlib import Path

# Read API key
API_KEY = os.environ.get("OPENROUTER_API_KEY")
if not API_KEY:
    env_file = Path(os.path.expanduser("~/.hermes/.env"))
    if env_file.exists():
        for line in open(env_file):
            if line.startswith("OPENROUTER_API_KEY=") and "***" not in line:
                API_KEY = line.split("=", 1)[1].strip().strip("'\"")
                break
if not API_KEY:
    print("ERROR: No OPENROUTER_API_KEY found")
    exit(1)

OUTPUT_DIR = Path("/home/bob/books/The_Unwritten_Future/output/part_images")
OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

PARTS = [
    {
        "name": "part1_ignition",
        "prompt": "Black and white pencil sketch, highly detailed photorealistic graphite drawing, 2048x2048 pixels, of a young boy's hand reaching toward an electrical outlet on a 1950s wooden cabin wall in northern Michigan. A set of car keys with carved wooden fob on a countertop. Summer light through cabin windows casting soft shadows. Fine cross-hatching, soft graphite shading, no text, no labels.",
    },
    {
        "name": "part2_building",
        "prompt": "Black and white pencil sketch, highly detailed photorealistic graphite drawing, 2048x2048 pixels, of a 1960s garage workshop. A half-built wooden boat on trailer, balsa wood airplane models hanging from ceiling, tools on workbench. A father and young son at a scroll saw. Sawdust in air, warm light from single bare bulb. Fine cross-hatching, no text, no labels.",
    },
    {
        "name": "part3_particle",
        "prompt": "Black and white pencil sketch, highly detailed photorealistic graphite drawing, 2048x2048 pixels, interior of the Fermilab particle accelerator control room 1970s. Racks of analog electronics with glowing vacuum tubes and indicator lights, a young engineer in button-down shirt studying schematics. Oscilloscope screens showing waveforms. Concrete walls, industrial lighting. Fine cross-hatching, no text, no labels.",
    },
    {
        "name": "part4_forward",
        "prompt": "Black and white pencil sketch, highly detailed photorealistic graphite drawing, 2048x2048 pixels, a quiet hospital room scene. A middle-aged man sitting beside a bed holding his wife's hand, medical equipment in background, soft light through blinds casting shadows on wall. Grief and care. Fine cross-hatching, no text, no labels.",
    },
    {
        "name": "part5_future",
        "prompt": "Black and white pencil sketch, highly detailed photorealistic graphite drawing, 2048x2048 pixels, futuristic workshop in a space colony. A child holding a broken piece of wood, robot arm and 3D printer nearby. Through a window, Earth visible in black sky. Old tools and new ones side by side. Fine cross-hatching, hopeful atmosphere, no text, no labels.",
    },
]

def generate_image(name, prompt, api_key, model="google/gemini-2.5-flash-image", max_retries=3):
    url = "https://openrouter.ai/api/v1/chat/completions"
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "HTTP-Referer": "https://hermes.local",
        "X-Title": "Hermes Image Generation"
    }
    for attempt in range(max_retries):
        try:
            payload = {
                "model": model,
                "messages": [{"role": "user", "content": [{"type": "text", "text": prompt}]}]
            }
            print(f"  [{name}] attempt {attempt+1}/{max_retries}...")
            resp = requests.post(url, json=payload, headers=headers, timeout=180)
            resp.raise_for_status()
            result = resp.json()
            images = result["choices"][0]["message"].get("images", [])
            if not images:
                print(f"  No images, retrying...")
                time.sleep(5)
                continue
            img_data = images[0]
            img_url = img_data["image_url"]["url"]

            if img_url.startswith("data:image/png;base64,"):
                b64 = img_url.split(",", 1)[1]
                img_bytes = base64.b64decode(b64)
            elif img_url.startswith("http"):
                img_resp = requests.get(img_url, timeout=60)
                img_bytes = img_resp.content
            else:
                print(f"  Unknown format, retrying...")
                time.sleep(5)
                continue

            # Save as PNG first
            png_path = OUTPUT_DIR / f"{name}.png"
            with open(png_path, "wb") as f:
                f.write(img_bytes)

            # Convert to high-quality JPEG for smaller file
            from PIL import Image
            img = Image.open(png_path)

            # Convert to grayscale if needed
            if img.mode != 'L':
                img = img.convert('L')

            # Save as JPEG quality 95 for best quality
            jpg_path = OUTPUT_DIR / f"{name}.jpg"
            img.save(jpg_path, "JPEG", quality=95, optimize=True)

            # Also save optimized PNG
            img.save(png_path, "PNG", optimize=True)

            print(f"  ✓ {name}.jpg ({jpg_path.stat().st_size//1024}KB) + .png ({png_path.stat().st_size//1024}KB)")
            return str(jpg_path)
        except Exception as e:
            print(f"  ✗ Error: {e}")
            if attempt < max_retries - 1:
                time.sleep(10)
    return None

print("=" * 60)
print("REGENERATING 5 PART SKETCHES (2048x2048)")
print("=" * 60)

results = []
for idx, part in enumerate(PARTS):
    print(f"\n[{idx+1}/5] {part['name']}")
    path = generate_image(part["name"], part["prompt"], API_KEY)
    results.append({"name": part["name"], "path": path})
    if idx < len(PARTS) - 1:
        time.sleep(5)

# Save results
with open(OUTPUT_DIR / "generation_results.json", "w") as f:
    json.dump(results, f, indent=2)

success = sum(1 for r in results if r["path"])
print(f"\nDone: {success}/5 generated")
for r in results:
    print(f"  {'✓' if r['path'] else '✗'} {r['name']}: {r['path'] or 'FAILED'}")
