"""
Add TOC page numbers to a WeasyPrint HTML manuscript using target-counter().

Usage: python3 toc-page-numbers.py manuscript.html [output.html]

This script:
1. Adds 'id' attributes to all chapter/part heading tags
2. Converts TOC entries from plain text to <a href="#id"> links
3. Injects CSS with target-counter for automatic page numbers
"""

import re, sys

def add_toc_page_numbers(html):
    """Add target-counter page number CSS + heading IDs + TOC links."""

    # 1. Add IDs to chapter headings (both h2 and h1 part titles)
    chapter_ids = {}
    for m in re.finditer(r'<(h[12] class="[^"]*chapter[^"]*")>(Chapter \w+: .*?)</h\d>', html, re.IGNORECASE):
        tag_open, ch_text = m.group(1), m.group(2)
        ch_id = ch_text.lower().replace(' ', '-').replace(':', '')
        ch_id = re.sub(r'[^a-z0-9-]', '', ch_id)
        chapter_ids[ch_text] = ch_id
        html = html.replace(
            f'<{tag_open}>{ch_text}</h{m.group(0)[-3]}>',
            f'<{tag_open} id="{ch_id}">{ch_text}</h{m.group(0)[-3]}>'
        )

    part_ids = {}
    for m in re.finditer(r'<(h[12] class="[^"]*part[^"]*")>(Part \w+: .*?)</h\d>', html, re.IGNORECASE):
        tag_open, pt_text = m.group(1), m.group(2)
        pt_id = pt_text.lower().replace(' ', '-').replace(':', '')
        pt_id = re.sub(r'[^a-z0-9-]', '', pt_id)
        part_ids[pt_text] = pt_id
        html = html.replace(
            f'<{tag_open}>{pt_text}</h{m.group(0)[-3]}>',
            f'<{tag_open} id="{pt_id}">{pt_text}</h{m.group(0)[-3]}>'
        )

    # 2. Convert TOC entries to links with href pointing to the IDs
    for pt_text, pt_id in part_ids.items():
        old_toc = f'<p class="part">{pt_text}</p>'
        new_toc = f'<p class="part"><a href="#{pt_id}">{pt_text}</a></p>'
        html = html.replace(old_toc, new_toc)

    for ch_text, ch_id in chapter_ids.items():
        old_toc = f'<p class="chapter">{ch_text}</p>'
        new_toc = f'<p class="chapter"><a href="#{ch_id}">{ch_text}</a></p>'
        html = html.replace(old_toc, new_toc)

    # 3. Inject CSS for target-counter
    toc_css = '''
/* TOC page numbers via WeasyPrint target-counter */
.toc a {
    text-decoration: none;
    color: inherit;
    display: block;
}
.toc a::after {
    content: "  " target-counter(attr(href url), page);
    float: right;
    color: #555;
    font-size: 10pt;
}
'''
    html = html.replace('</style>', toc_css + '\n</style>')

    return html

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: python3 toc-page-numbers.py input.html [output.html]")
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2] if len(sys.argv) > 2 else input_path

    with open(input_path) as f:
        html = f.read()

    html = add_toc_page_numbers(html)

    with open(output_path, 'w') as f:
        f.write(html)

    print(f"Added TOC page numbers to {output_path}")
    print(f"  Chapters linked: {len([k for k in html.split('href=\"#') if 'chapter-' in k.lower()])}")
    print(f"  Parts linked: {len([k for k in html.split('href=\"#') if 'part-' in k.lower()])}")
"}

